// 计算昨日日期
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const dateStr = yesterday.toISOString().slice(0, 10);

// 计算7天前日期
const weekAgo = new Date();
weekAgo.setDate(weekAgo.getDate() - 7);
const weekAgoStr = weekAgo.toISOString().slice(0, 10);

return [{ json: { date: dateStr, weekStart: weekAgoStr } }];

// 格式化报告数据为 Ollama 提示词
const report = $input.first().json;
const date = $('计算日期范围').first().json.date;

// 营养摘要
const nutrition = report.nutrition?.avg || {};
const nutritionText = nutrition.kcal
  ? `热量 ${nutrition.kcal}kcal, 蛋白质 ${nutrition.protein_g}g, 碳水 ${nutrition.carb_g}g, 脂肪 ${nutrition.fat_g}g, 钠 ${nutrition.sodium_mg}mg, 钾 ${nutrition.potassium_mg}mg`
  : '暂无饮食数据';

// 液体平衡
const fluid = report.fluid_balance || {};
const fluidText = `摄入 ${fluid.total_intake_ml || 0}ml, 排出 ${fluid.total_output_ml || 0}ml, 平衡 ${fluid.balance_ml || 0}ml`;

// 血压
const bp = report.blood_pressure || {};
const bpStats = bp.stats;
const bpEntries = bp.entries || [];
const bpText = bpStats
  ? `平均 ${bpStats.avg_systolic}/${bpStats.avg_diastolic} mmHg, 脉搏 ${bpStats.avg_pulse}bpm, ${bpStats.count}次记录\n最近读数: ${bpEntries.slice(0, 3).map(e => `${e.systolic}/${e.diastolic}`).join(', ')}`
  : '暂无血压数据';

// 透析
const dialysis = report.dialysis || {};
const dialysisStats = dialysis.stats;
const dialysisEntries = dialysis.entries || [];
const dialysisText = dialysisStats
  ? `${dialysisStats.count}次透析, 平均${dialysisStats.avg_duration_min}分钟, 总超滤${dialysisStats.total_uf_ml}ml\n最近: ${dialysisEntries.slice(0, 2).map(e => `${e.date} ${e.modality} ${e.duration_min || '?'}min UF:${e.ultrafiltration_ml || '?'}ml`).join('; ')}`
  : '暂无透析数据';

// 疼痛
const pain = report.pain || {};
const painStats = pain.stats;
const painText = painStats
  ? `平均${painStats.avg_score}分, 最高${painStats.max_score}分, 最低${painStats.min_score}分, ${painStats.count}次记录`
  : '暂无疼痛数据';

// 用药
const meds = report.medications || [];
const medsText = meds.length > 0
  ? meds.map(m => `${m.name} ${m.dose_amount || ''}${m.dose_unit || ''} ${m.frequency || ''} (${m.indication || m.category || ''})`).join('; ')
  : '暂无用药';

// 日记
const diary = report.diary || {};
const diaryStats = diary.stats;
const diaryText = diaryStats
  ? `心情 ${diaryStats.avg_mood}/5, 精力 ${diaryStats.avg_energy}/5, 睡眠 ${diaryStats.avg_sleep}/5`
  : '暂无日记数据';

// 体重
const weight = report.weight || [];
const weightText = weight.length > 0
  ? `最近体重: ${weight[0].kg}kg (${weight[0].date})`
  : '暂无体重数据';

// 化验
const labs = report.lab_results || [];
const labsText = labs.length > 0
  ? labs.slice(0, 5).map(lr => `${lr.biomarker_name}: ${lr.value_numeric ?? lr.value_text} ${lr.unit_ucum}`).join('; ')
  : '暂无化验数据';

// 构建提示词
const prompt = `你是一位专业的肾内科健康顾问。请根据以下患者过去7天的健康数据，生成一份简洁的每日健康摘要报告（中文）。

## 数据（截至 ${date}）

### 营养摄入（日均）
${nutritionText}

### 液体平衡
${fluidText}

### 血压
${bpText}

### 透析
${dialysisText}

### 疼痛
${painText}

### 当前用药
${medsText}

### 情绪/症状日记
${diaryText}

### 体重
${weightText}

### 最近化验
${labsText}

## 请生成以下内容的报告：

1. **血压趋势分析**：评估血压控制情况，是否有异常波动
2. **透析反应评估**：如有透析数据，分析超滤是否充分，有无并发症风险
3. **饮食建议**：基于营养数据和肾病饮食原则（低磷低钾低钠优质低蛋白），给出具体建议
4. **异常提醒**：标注任何需要关注的异常指标
5. **今日建议**：1-2条简短的行动建议

请保持报告简洁，总字数控制在300字以内。`;

return [{ json: { prompt, date } }];

// 提取 Ollama 生成的摘要文本
const ollamaResponse = $input.first().json;
const summary = ollamaResponse.response || '生成失败';
const date = $('格式化数据为提示词').first().json.date;

// 构建钉钉消息
const markdown = {
  title: `每日健康摘要 (${date})`,
  text: `## 每日健康摘要\n**${date}**\n\n${summary}\n\n---\n*由 health-mcp + Ollama 自动生成*`
};

return [{ json: { markdown } }];
